10		"time"
11	
12		"github.com/entireio/cli/cmd/entire/cli/api"
13		"github.com/entireio/cli/cmd/entire/cli/auth"
14		"github.com/entireio/cli/cmd/entire/cli/logging"
15		"github.com/entireio/cli/cmd/entire/cli/search"
16		"github.com/entireio/cli/internal/coreapi"
17	)
18	
19	// semanticSearchV4CellTimeout bounds each per-cell v4 query (token exchange +
20	// the query-serve call), mirroring codeSearchCellTimeout.
21	const semanticSearchV4CellTimeout = 30 * time.Second
22	
23	// semanticSearchControlPlaneTimeout bounds each control-plane discovery call
24	// (repo index / repo lookup) on the v4 path.
25	const semanticSearchControlPlaneTimeout = 10 * time.Second
26	
27	// semanticSearcher performs one semantic search. The command layer builds one
28	// per invocation (newSemanticSearcher) and every entry point — the one-shot
29	// command, the TUI's initial fetch, interactive re-searches, and pagination —
30	// calls through it, so all of them share one discovery cache.
31	type semanticSearcher func(ctx context.Context, cfg search.Config) (*search.Response, error)
32	
33	// newSemanticSearcher returns the semantic-search entry for this invocation: a
34	// v4 query-serve session (ENT-1055) that fans out across entire-api cells and
35	// caches control-plane discovery across calls.
36	func newSemanticSearcher(insecureHTTP bool) semanticSearcher {
37		s := &semanticSearchV4Session{insecureHTTP: insecureHTTP}
38		return s.search
39	}
40	
41	// loginHintErr maps auth.ErrNotLoggedIn to the standard login hint; other
42	// errors pass through unchanged.
43	func loginHintErr(err error) error {
44		if errors.Is(err, auth.ErrNotLoggedIn) {
45			return errors.New("not authenticated. Run 'entire login' to authenticate")
46		}
47		return err
48	}
49	
50	// semanticSearchV4Session holds per-invocation state for the v4 query-serve
51	// path. Control-plane discovery (the repo index, per-slug repo lookups, the
52	// cluster catalog) is stable for the life of one command, so it is resolved
53	// once and reused across TUI re-searches and pagination instead of paying
54	// several network round trips per keystroke-search. Identity tokens are NOT
55	// cached here — fanOutCells mints them per search (at most one per
56	// jurisdiction), which keeps expiry handling in the auth layer.
57	type semanticSearchV4Session struct {
58		insecureHTTP bool
59	
60		mu         sync.Mutex
61		coreClient *coreapi.Client
62		clusters   *cachedClusterClient
63		fullIndex  *coreapi.ListReposOutputBody        // unfiltered index, fetched at most once
64		slugRepos  map[string][]coreapi.RepoIndexEntry // per-filter exact-match lookups
65	}
66	
67	// search performs a v4 query-serve search across every cell that hosts the
68	// caller's in-scope repos, then merges the per-cell responses into one
69	// response. It is the semantic sibling of searchAllCells (code): resolve
70	// scope → group by hosting cell → one query-serve call per cell → tiered
71	// merge.
72	//
73	// Scope follows Config.ScopeSlugs — an explicit repo filter wins over
74	// --all-repos (the more specific filter scopes the search):
75	//   - unfiltered (repo:* / --all-repos with no explicit filter) → every cell
76	//     is queried with NO repo param, so query-serve returns everything the
77	//     caller's token authorizes there (matching the BFF and keeping the query
78	//     small for users with many repos).
79	//   - explicit repo filter(s) or the current-repo default → the slugs are
80	//     resolved via truncation-proof exact-match lookups and each cell is
81	//     scoped to the ULIDs it hosts.
82	//
83	// Completeness caveats (truncated index, failed regions) are returned as
84	// Response.Warnings for the caller to surface.
85	func (s *semanticSearchV4Session) search(ctx context.Context, cfg search.Config) (*search.Response, error) {
86		if err := search.ValidateRepoFilters(cfg.Repos); err != nil {
87			return nil, err //nolint:wrapcheck // user-facing validation message
88		}
89	
90		coreClient, err := s.client()
91		if err != nil {
92			if errors.Is(err, auth.ErrNotLoggedIn) {
93				return nil, loginHintErr(err)
94			}
95			return nil, fmt.Errorf("semantic search: resolving control-plane client: %w", err)
96		}
97	
98		slugs, allRepos := cfg.ScopeSlugs()
99		var cells []cellGroup
100		var skipped []string
101		var warnings []string
102		indexTruncated := false
103		scoped := !allRepos
104		if scoped {
105			if len(slugs) == 0 {
106				return nil, errors.New("semantic search: could not determine the repository to search")
107			}
108			entries, err := s.resolveScope(ctx, slugs)
109			if err != nil {
110				return nil, err
111			}
112			// Scoped requests pin the picked placement's ULID (repoIDs below),
113			// which query-serve resolves from its all-accessible byID set.
114			cells, skipped = groupReposByCell(entries)
115		} else {
116			index, err := s.listFullIndex(ctx)
117			if err != nil {
118				return nil, fmt.Errorf("semantic search: listing repos for cell discovery: %w", err)
119			}
120			if index.Truncated {
121				// Debug, not Warn: the user-facing channel is the Warnings entry;
122				// slog's default handler would print a Warn straight to stderr on
123				// commands whose context carries no logger.
124				logging.Debug(ctx, "semantic search: repo index truncated; cross-repo results may be incomplete")
125				warnings = append(warnings, "repo index truncated; cross-repo results may be incomplete")
126				indexTruncated = true
127			}
128			// Broad requests send no repo pins; query-serve narrows pin-less
129			// scope by the same election routedRepoPlacement picks by (ENT-1776),
130			// so one grouping serves both request shapes.
131			cells, skipped = groupReposByCell(index.Repos)
132		}
133		skipped = reportableSkippedRepos(ctx, scoped, len(cells), skipped)
134		if len(skipped) > 0 {
135			warnings = append(warnings, fmt.Sprintf("skipped %d repo(s) with no searchable placement (missing or not ready): %s", len(skipped), strings.Join(skipped, ", ")))
136		}
137		// The BFF's scope-loss channels (search.ts): a truncated repo index means
138		// broad coverage silently misses repos; an explicitly-filtered repo
139		// skipped as not-ready narrows the promised scope. Unfiltered skips stay
140		// silent — nothing advertised was narrowed.
141		scopeNarrowed := scoped && len(skipped) > 0
142	
143		if len(cells) == 0 {
144			resp := &search.Response{Results: []search.Result{}, Page: 1, Warnings: warnings, Counts: &search.TypeCounts{}}
145			if indexTruncated {
146				// Every facet count is a lower bound, not an exact zero — same
147				// contract as the BFF's zero-routable-cells answer.
148				resp.Truncated = true
149				resp.CountsLowerBound = map[string]bool{
150					facetRepos: true, facetCheckpoints: true, facetCommits: true, facetPRs: true, facetSessions: true,
151				}
152			}
153			if indexTruncated || scopeNarrowed {
154				resp.Partial = true
155				resp.CoverageIncomplete = true
156			}
157			return resp, nil
158		}
159		resolveCellBaseURLs(ctx, s.clusterClient(coreClient), cells)
160	
161		results, err := fanOutCells(ctx, s.insecureHTTP, semanticSearchV4CellTimeout, cells, func(ctx context.Context, group cellGroup, client *api.Client) (*search.Response, error) {
162			// Scoped: restrict the cell to the ULIDs it hosts. Unfiltered: send no
163			// repo param and let query-serve search everything the token
164			// authorizes in that cell (avoids per-request repo-filter caps for
165			// large accounts).
166			var repoIDs []string
167			if scoped {
168				repoIDs = group.repoIDs
169			}
170			return search.CellV4(ctx, client, cfg, repoIDs)
171		})
172		if err != nil {
173			if errors.Is(err, auth.ErrNotLoggedIn) {
174				return nil, loginHintErr(err)
175			}
176			return nil, fmt.Errorf("semantic search: %w", err)
177		}
178	
179		resp, err := mergeSemanticV4Responses(ctx, cfg.Limit, cfg.Page, results)
180		if err != nil {
181			return nil, err
182		}
183		resp.Warnings = append(warnings, resp.Warnings...)
184		if indexTruncated {
185			resp.Truncated = true
186		}
187		if indexTruncated || scopeNarrowed {
188			resp.Partial = true
189			resp.CoverageIncomplete = true
190		}
191		return resp, nil
192	}
193	
194	// client returns the cached control-plane client, creating it on first use.
195	func (s *semanticSearchV4Session) client() (*coreapi.Client, error) {
196		s.mu.Lock()
197		defer s.mu.Unlock()
198		if s.coreClient != nil {
199			return s.coreClient, nil
200		}
201		c, err := coreapi.New()
202		if err != nil {
203			return nil, err
204		}
205		s.coreClient = c
206		return c, nil
207	}
208	
209	// listFullIndex fetches (once) and caches the caller's full repo index, used
210	// for unfiltered searches and raw-ID filter matching.
211	func (s *semanticSearchV4Session) listFullIndex(ctx context.Context) (*coreapi.ListReposOutputBody, error) {
212		s.mu.Lock()
213		defer s.mu.Unlock()
214		if s.fullIndex != nil {
215			return s.fullIndex, nil
216		}
217		reposCtx, cancel := context.WithTimeout(ctx, semanticSearchControlPlaneTimeout)
218		defer cancel()
219		index, err := s.coreClient.ListRepos(reposCtx, coreapi.ListReposParams{})
220		if err != nil {
221			return nil, err
222		}
223		s.fullIndex = index
224		return index, nil
225	}
226	
227	// resolveScope resolves explicit repo filters (or the current-repo default)
228	// to index entries, deduped by repo ID. owner/name slugs use the exact-match
229	// ListRepos filter — immune to index truncation on large accounts — while raw
230	// IDs (no slash) fall back to matching against the full index. Zero matches
231	// is a clear error; a partially matched multi-repo filter proceeds with the
232	// matches, like resolveRepoFilters does for code search.
233	func (s *semanticSearchV4Session) resolveScope(ctx context.Context, slugs []string) ([]coreapi.RepoIndexEntry, error) {
234		var entries []coreapi.RepoIndexEntry
235		seen := make(map[string]bool, len(slugs))
236		for _, f := range slugs {
237			matched, err := s.lookupFilter(ctx, f)
238			if err != nil {
239				return nil, err
240			}
241			for _, e := range matched {
242				if !seen[e.ID] {
243					seen[e.ID] = true
244					entries = append(entries, e)
245				}
246			}
247		}
248		if len(entries) == 0 {
249			return nil, fmt.Errorf("no matching repositories found for %v (is the repo mirrored to Entire?)", slugs)
250		}
251		return entries, nil
252	}
253	
254	// lookupFilter resolves one repo filter to index entries, cached per session.
255	// Matching mirrors resolveRepoFilters: a gh/ prefix is stripped, owner/name
256	// matches full_name (case-insensitive, server-side exact match), and a raw
257	// ULID matches the index entry's ID.
258	func (s *semanticSearchV4Session) lookupFilter(ctx context.Context, filter string) ([]coreapi.RepoIndexEntry, error) {
259		s.mu.Lock()
260		if cached, ok := s.slugRepos[filter]; ok {
261			s.mu.Unlock()
262			return cached, nil
263		}
264		s.mu.Unlock()
265	
266		slug := strings.TrimPrefix(filter, "gh/")
267		var matched []coreapi.RepoIndexEntry
268		if strings.Contains(slug, "/") {
269			lookupCtx, cancel := context.WithTimeout(ctx, semanticSearchControlPlaneTimeout)
270			defer cancel()
271			out, err := s.coreClient.ListRepos(lookupCtx, coreapi.ListReposParams{Filter: coreapi.NewOptString(slug)})
272			if err != nil {
273				return nil, fmt.Errorf("semantic search: resolving repository %q: %w", filter, err)
274			}
275			matched = out.Repos
276		} else {
277			// Raw repo ID — the exact-match filter only matches full_name, so
278			// match by ID against the full index.
279			index, err := s.listFullIndex(ctx)
280			if err != nil {
281				return nil, fmt.Errorf("semantic search: resolving repository %q: %w", filter, err)
282			}
283			_, matched = resolveRepoFilters([]string{filter}, index.Repos)
284		}
285	
286		s.mu.Lock()
287		if s.slugRepos == nil {
288			s.slugRepos = make(map[string][]coreapi.RepoIndexEntry)
289		}
290		s.slugRepos[filter] = matched
291		s.mu.Unlock()
292		return matched, nil
293	}
294	
295	// clusterClient returns a cellCoreClient whose ListClusters is memoized for
296	// the session, so re-searches don't refetch the (stable) cluster catalog.
297	func (s *semanticSearchV4Session) clusterClient(inner *coreapi.Client) cellCoreClient {
298		s.mu.Lock()
299		defer s.mu.Unlock()
300		if s.clusters == nil {
301			s.clusters = &cachedClusterClient{inner: inner}
302		}
303		return s.clusters
304	}
305	
306	// cachedClusterClient is a cellCoreClient that caches a successful
307	// ListClusters result; failures are not cached, so the next call retries.
308	// The other methods delegate unchanged.
309	type cachedClusterClient struct {
310		inner cellCoreClient
311	
312		mu       sync.Mutex
313		clusters *coreapi.ListClustersOutputBody
314	}
315	
316	func (c *cachedClusterClient) ListClusters(ctx context.Context) (*coreapi.ListClustersOutputBody, error) {
317		c.mu.Lock()
318		defer c.mu.Unlock()
319		if c.clusters != nil {
320			return c.clusters, nil
321		}
322		out, err := c.inner.ListClusters(ctx)
323		if err != nil {
324			return nil, err //nolint:wrapcheck // transparent delegation
325		}
326		c.clusters = out
327		return out, nil
328	}
329	
330	func (c *cachedClusterClient) GetRepo(ctx context.Context, params coreapi.GetRepoParams) (*coreapi.Repo, error) {
331		return c.inner.GetRepo(ctx, params) //nolint:wrapcheck // transparent delegation
332	}
333	
334	func (c *cachedClusterClient) ListRepos(ctx context.Context, params coreapi.ListReposParams) (*coreapi.ListReposOutputBody, error) {
335		return c.inner.ListRepos(ctx, params) //nolint:wrapcheck // transparent delegation
336	}
337	
338	// tierOf returns a result's tier, or -1 when unset (dropped by the merge,
339	// like every tier outside 0/1 — see rankSemanticResults).
340	func tierOf(r search.Result) int {
341		if r.Meta.Tier == nil {
342			return -1
343		}
344		return *r.Meta.Tier
345	}
346	
347	func bm25Of(r search.Result) float64 {
348		if r.Meta.BM25Score != nil {
349			return *r.Meta.BM25Score
350		}
351		return 0
352	}
353	
354	// rerankOf returns query-serve's cross-encoder relevance score, or 0 when the
355	// row was not reranked (its cell fell back). Rows without a score sort after
356	// reranked ones, matching the BFF's rerankOf.
357	func rerankOf(r search.Result) float64 {
358		if r.Meta.RerankScore != nil {
359			return *r.Meta.RerankScore
360		}
361		return 0
362	}
363	
364	// semanticCellPage is one cell's successful response.
365	type semanticCellPage struct {
366		body *search.Response
367	}
368	
369	// classifySemanticCells splits per-cell outcomes into successful pages, hard
370	// failures, and quietly-skipped cells. A cell is skipped — not failed — when
371	// it can't serve the search yet: its gateway has no query-serve route, or the
372	// cluster catalog doesn't expose the placement's jurisdiction at all (a cell
373	// mid-onboarding). Neither is worth warning the user about on every search.
374	func classifySemanticCells(ctx context.Context, results []cellCallResult[*search.Response]) (pages []semanticCellPage, failed []string, lastErr error) {
375		var skipped, unmatched []string
376		var unmatchedErr error
377		for _, r := range results {
378			switch {
379			case errors.Is(r.err, search.ErrCellUnavailable), errors.Is(r.err, auth.ErrNoCellForJurisdiction):
380				skipped = append(skipped, r.group.label())
381			case errors.Is(r.err, search.ErrRepoFilterUnmatched):
382				// The cell answered; the repo filter just matched nothing there.
383				// Quiet like a skip when another cell has results, but if NO cell
384				// matches it must surface as a repo problem, never a region one.
385				unmatched = append(unmatched, r.group.label())
386				unmatchedErr = r.err
387			case r.err != nil:
388				lastErr = r.err
389				failed = append(failed, r.group.label())
390			case r.value != nil:
391				pages = append(pages, semanticCellPage{body: r.value})
392			}
393		}
394		if len(skipped) > 0 {
395			logging.Debug(ctx, "semantic search: cells without query-serve skipped", "skipped_cells", skipped)
396		}
397		if len(unmatched) > 0 {
398			// unmatchedErr carries the server's own message (CellV4 wraps it into
399			// the sentinel) — keep it visible here for diagnosis.
400			logging.Debug(ctx, "semantic search: cells where the repo filter matched nothing", "unmatched_cells", unmatched, "error", unmatchedErr.Error())
401		}
402		if len(pages) == 0 && lastErr == nil {
403			switch {
404			case len(unmatched) > 0:
405				// Takes priority over the region message: a cell answering proves
406				// its region serves semantic search.
407				lastErr = errNoRepoAvailable
408			case len(skipped) > 0:
409				lastErr = errNoRegionAvailable
410			}
411		}
412		return pages, failed, lastErr
413	}
414	
415	// errNoRepoAvailable is returned when at least one cell answered but none
416	// matched the repo filter. A typo'd name or missing access cannot reach this
417	// point — resolveScope already validated the slug against the control-plane
418	// repo index — so the message names only the causes that survive: query-serve
419	// hasn't indexed the repo, or its owner org isn't enabled for semantic search.
420	var errNoRepoAvailable = errors.New("semantic search cannot search this repo yet — it may not be indexed, or semantic search may not be enabled for its owner")
421	
422	// errNoRegionAvailable is returned when every queried cell lacks query-serve.
423	var errNoRegionAvailable = errors.New("semantic search is not yet available in the region(s) hosting this search")
424	
425	// tier0Row pairs a tier-0 result with its rank within the cell that returned
426	// it — the selection order the mixed-capability fallback preserves (see
427	// sortTier0Rows).
428	type tier0Row struct {
429		r        search.Result
430		cellRank int
431	}
432	
433	// rankSemanticResults buckets every page's rows and applies the SAME ordering
434	// the BFF's cross-cell merge uses (see the ordering contract on
435	// mergeSemanticV4Responses): repos first by retrieval score desc, then tier 0
436	// (sortTier0Rows), then tier 1 by rerank desc with retrieval Score tiebreak.
437	// Every other non-repo row — tier 2 (the retired ANN-only fallback, still
438	// emitted by un-redeployed cells) and rows with no tier at all — is DROPPED,
439	// exactly as the BFF drops them. Ordering by rerank score — not BM25 or the
440	// per-namespace retrieval Score — is what keeps the CLI in parity with the
441	// web: query-serve documents that Score "is not the field results are ordered
442	// by … sorting by it undoes reranking."
443	func rankSemanticResults(pages []semanticCellPage) (merged []search.Result) {
444		var repos, tier1 []search.Result
445		var tier0 []tier0Row
446		for _, p := range pages {
447			cellRank := 0
448			for _, r := range p.body.Results {
449				switch {
450				case r.Type == search.TypeRepo:
451					repos = append(repos, r)
452				case tierOf(r) == 0:
453					tier0 = append(tier0, tier0Row{r: r, cellRank: cellRank})
454					cellRank++
455				case tierOf(r) == 1:
456					tier1 = append(tier1, r)
457				}
458			}
459		}
460		sort.SliceStable(repos, func(i, j int) bool { return repos[i].Meta.Score > repos[j].Meta.Score })
461		merged = append(merged, repos...)
462		sortTier0Rows(tier0)
463		// Tier 1: rerank score decides, retrieval Score breaks ties. Rows whose
464		// cell fell back (no rerank score) sort last, matching the BFF.
465		sort.SliceStable(tier1, func(i, j int) bool {
466			if ri, rj := rerankOf(tier1[i]), rerankOf(tier1[j]); ri != rj {
467				return ri > rj
468			}
469			return tier1[i].Meta.Score > tier1[j].Meta.Score
470		})
471		for _, t := range tier0 {
472			merged = append(merged, t.r)
473		}
474		merged = append(merged, tier1...)
475		return merged
476	}
477	
478	// sortTier0Rows orders the tier-0 band the way the BFF's sortTier0 does
479	// (ENT-1431). When EVERY row was judged by the cross-encoder, rerank score
480	// decides and BM25 breaks ties. When any row is missing a rerank score — its
481	// cell predates tier-0 reranking — a global rerank sort would demote all of
482	// that cell's full-phrase hits regardless of relevance, so instead the rows are
483	// interleaved positionally (each cell's #1, then each cell's #2, …), preserving
484	// every cell's own selection order, with BM25 breaking ties between same-rank
485	// rows. Converges to rerank-first once every cell is current.
486	func sortTier0Rows(tier0 []tier0Row) {
487		allScored := true
488		for _, t := range tier0 {
489			if t.r.Meta.RerankScore == nil {
490				allScored = false
491				break
492			}
493		}
494		if allScored {
495			sort.SliceStable(tier0, func(i, j int) bool {
496				if ri, rj := rerankOf(tier0[i].r), rerankOf(tier0[j].r); ri != rj {
497					return ri > rj
498				}
499				return bm25Of(tier0[i].r) > bm25Of(tier0[j].r)
500			})
501			return
502		}
503		sort.SliceStable(tier0, func(i, j int) bool {
504			if tier0[i].cellRank != tier0[j].cellRank {
505				return tier0[i].cellRank < tier0[j].cellRank
506			}
507			return bm25Of(tier0[i].r) > bm25Of(tier0[j].r)
508		})
509	}
510	
511	// dedupSemanticResults removes cross-cell duplicate SESSION rows, keeping the
512	// first (higher-ranked) copy — the BFF's exact rule: sessions are the one type
513	// that legitimately repeats across cells (a crosslinked session attached to
514	// repos homed in different cells), while repo-bound types are canonical to one
515	// cell since the fan-out routes each repo to its single home placement
516	// (ENT-1672/ENT-1776). The key is the global session id when present, else the
517	// repo-qualified carrier checkpoint (server-folded legacy rows, ENT-1595);
518	// rows with neither are always kept.
519	func dedupSemanticResults(merged []search.Result) []search.Result {
520		seen := make(map[string]bool)
521		deduped := merged[:0]
522		for _, r := range merged {
523			if r.Type != search.TypeSession {
524				deduped = append(deduped, r)
525				continue
526			}
527			id := r.DedupID()
528			if id == "" {
529				deduped = append(deduped, r)
530				continue
531			}
532			key := r.Type + "\x00" + id
533			if seen[key] {
534				continue
535			}
536			seen[key] = true
537			deduped = append(deduped, r)
538		}
539		return deduped
540	}
541	
542	// Facet names for the wire maps (truncated_types / counts_lower_bound) — the
543	// BFF's RESULT_TYPE_TO_FACET values.
544	const (
545		facetRepos       = "repos"
546		facetCheckpoints = "checkpoints"
547		facetCommits     = "commits"
548		facetPRs         = "prs"
549		facetSessions    = "sessions"
550	)
551	
552	// semanticFacetOf maps a wire result type to its counts/truncation facet name
553	// (the BFF's RESULT_TYPE_TO_FACET). Unknown types have no facet: they are kept
554	// in results, exempt from the per-type cap, and counted only in the total.
555	func semanticFacetOf(typ string) (string, bool) {
556		switch typ {
557		case search.TypeRepo:
558			return facetRepos, true
559		case search.TypeCheckpoint:
560			return facetCheckpoints, true
561		case search.TypeCommit:
562			return facetCommits, true
563		case search.TypePR:
564			return facetPRs, true
565		case search.TypeSession:
566			return facetSessions, true
567		}
568		return "", false
569	}
570	
571	// capSemanticPerType applies the BFF's per-type window: walk the merged list
572	// in order and keep at most `limit` rows of each facet, recording which facets
573	// overflowed. Rows without a facet mapping are kept uncounted.
574	func capSemanticPerType(merged []search.Result, limit int) ([]search.Result, map[string]bool) {
575		truncated := make(map[string]bool)
576		if limit <= 0 {
577			return merged, truncated
578		}
579		perFacet := make(map[string]int, 5)
580		out := merged[:0]
581		for _, r := range merged {
582			facet, ok := semanticFacetOf(r.Type)
583			if !ok {
584				out = append(out, r)
585				continue
586			}
587			perFacet[facet]++
588			if perFacet[facet] > limit {
589				truncated[facet] = true
590				continue
591			}
592			out = append(out, r)
593		}
594		return out, truncated
595	}
596	
597	// deriveSemanticCounts computes total and per-type counts from the FINAL
598	// merged list — the BFF's per-type contract (ENT-1363): counts describe
599	// exactly what the caller can see, never the cells' corpus-count passes,
600	// with counts_lower_bound marking the facets whose lists were capped.
601	func deriveSemanticCounts(merged []search.Result) (int, *search.TypeCounts) {
602		counts := &search.TypeCounts{}
603		for _, r := range merged {
604			switch r.Type {
605			case search.TypeRepo:
606				counts.Repos++
607			case search.TypeCheckpoint:
608				counts.Checkpoints++
609			case search.TypeCommit:
610				counts.Commits++
611			case search.TypePR:
612				counts.PRs++
613			case search.TypeSession:
614				counts.Sessions++
615			}
616		}
617		return len(merged), counts
618	}
619	
620	// mergeSemanticV4Responses interleaves per-cell query-serve responses into
621	// one final page. THE CROSS-CELL MERGE ORDERING CONTRACT lives here and in
622	// the BFF's mergeCellResponses (entire.io api/src/routes/search.ts) — the two
623	// implementations must stay byte-identical (ENT-1777); change one, change
624	// both, and update this block:
625	//
626	//  1. Band order: repo rows first (retrieval score desc), then tier 0, then
627	//     tier 1. Tier 2 and tier-less non-repo rows are dropped — the ANN-only
628	//     fallback tier is retired and only un-redeployed cells still emit it.
629	//     Band order deliberately overrides each cell's own post-fold final
630	//     order (entire-search#181 folds after ranking): the clients match each
631	//     other, not the leaf.
632	//  2. Tier 0: when every row carries a rerank score, rerank desc with BM25
633	//     tiebreak; when any cell predates tier-0 reranking, positional
634	//     interleave by in-cell rank with BM25 tiebreak (sortTier0Rows). Tier 1:
635	//     rerank desc, retrieval Score tiebreak. All sorts are STABLE — equal
636	//     keys keep cell-response order.
637	//  3. Dedupe AFTER ordering, BEFORE the per-type cap, sessions only, first
638	//     (highest-ranked) copy wins (dedupSemanticResults).
639	//  4. Per-type window: at most `limit` rows of each facet, overflow recorded
640	//     in truncated_types, unioned with the cells' own truncated_types
641	//     (capSemanticPerType). No global cut.
642	//  5. Counts and total derive from the FINAL list (deriveSemanticCounts);
643	//     counts_lower_bound == the capped facets.
644	//  6. Flags: truncated = any cell truncated; partial = truncated ∨ any cell
645	//     failed ∨ any cell partial ∨ mixed rerank capability; coverage_incomplete
646	//     = the same minus rerank-mix; reranked = every cell reranked (emitted
647	//     when any cell reported the field).
648	//
649	// Rerank scores share a space across cells (same Cohere model), so
650	// interleaving is meaningful. All-cells-failed is an error; a partial failure
651	// is noted in Warnings (and the flags) and the surviving cells are merged.
652	func mergeSemanticV4Responses(ctx context.Context, limit, page int, results []cellCallResult[*search.Response]) (*search.Response, error) {
653		pages, failed, lastErr := classifySemanticCells(ctx, results)
654		if len(pages) == 0 {
655			if lastErr != nil {
656				return nil, fmt.Errorf("semantic search: %w", lastErr)
657			}
658			return &search.Response{Results: []search.Result{}, Page: 1}, nil
659		}
660		var warnings []string
661		if len(failed) > 0 {
662			// Debug, not Warn: the warning below already reaches the user via
663			// Response.Warnings, and slog's default handler would print a Warn
664			// straight to stderr on commands whose context carries no logger.
665			logging.Debug(ctx, "semantic search: partial failure; results may be incomplete",
666				"succeeded", len(pages), "total", len(results), "failed_cells", failed)
667			warnings = append(warnings, fmt.Sprintf("search failed in %d of %d regions; results may be incomplete", len(failed), len(pages)+len(failed)))
668		}
669	
670		merged := rankSemanticResults(pages)
671		merged = dedupSemanticResults(merged)
672		merged, truncatedTypes := capSemanticPerType(merged, limit)
673		for _, p := range pages {
674			for facet, v := range p.body.TruncatedTypes {
675				if v {
676					truncatedTypes[facet] = true
677				}
678			}
679		}
680		if merged == nil {
681			merged = []search.Result{}
682		}
683	
684		total, counts := deriveSemanticCounts(merged)
685		resp := &search.Response{
686			Results:  merged,
687			Total:    total,
688			Page:     max(page, 1),
689			Counts:   counts,
690			Warnings: warnings,
691		}
692		if len(truncatedTypes) > 0 {
693			resp.TruncatedTypes = truncatedTypes
694			resp.CountsLowerBound = make(map[string]bool, len(truncatedTypes))
695			for facet := range truncatedTypes {
696				resp.CountsLowerBound[facet] = true
697			}
698		}
699	
700		anyRerankedField, anyReranked, allReranked := false, false, true
701		for _, p := range pages {
702			if p.body.Truncated {
703				resp.Truncated = true
704			}
705			if p.body.Partial {
706				resp.Partial = true
707				resp.CoverageIncomplete = true
708			}
709			if p.body.Reranked != nil {
710				anyRerankedField = true
711				if *p.body.Reranked {
712					anyReranked = true
713				} else {
714					allReranked = false
715				}
716			} else {
717				allReranked = false
718			}
719		}
720		if len(failed) > 0 || resp.Truncated {
721			resp.Partial = true
722			resp.CoverageIncomplete = true
723		}
724		if anyReranked && !allReranked {
725			// Mixed rerank capability skews ordering but not coverage — partial
726			// without coverage_incomplete, matching the BFF.
727			resp.Partial = true
728		}
729		if anyRerankedField {
730			resp.Reranked = &allReranked
731		}
732		return resp, nil
733	}
734

